/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: AppShell
 * Internal
 *   Functions: skipToMainContent, PrimaryNavigation, AppShellContent
 *   Constants: destinations, TopSearch, PlaylistSidebar, LanguageSelector, ShellPanelResizers, NowPlayingAside,
 *              PlayerBar, VideoTheater, GlobalRoomInvitations, AccountEntry, AdminControls
 * @end-catalog */

import {
  lazy,
  Suspense,
  useEffect,
  useRef,
  useState,
  type MouseEvent
} from 'react';
import { useQuery } from '@tanstack/react-query';
import { Link, NavLink, Outlet, useLocation, useNavigate } from 'react-router';

import { listenerCapabilitiesQuery } from '../api/listenerCapabilities';
import { Icon, type IconName } from '../components/Icon';
import { SearchQueryProvider } from '../features/search/SearchQueryProvider';
import { useSocialAvailability } from '../features/social/socialAvailability';
import { RouteAnnouncer } from './RouteAnnouncer';
import { useLocalization } from '../localization/LocalizationProvider';
import type { MessageKey } from '../localization/contract';
import { playerStore, usePlayer } from '../player';
import styles from './AppShell.module.css';

const destinations: Array<{ labelKey: MessageKey; path: string; icon: IconName }> = [
  { labelKey: 'shell.nav.home', path: '/', icon: 'home' },
  { labelKey: 'shell.nav.search', path: '/search', icon: 'search' },
  { labelKey: 'shell.nav.library', path: '/library', icon: 'library' },
  { labelKey: 'social.nav', path: '/social', icon: 'account' }
];

const TopSearch = lazy(() => import('./TopSearch'));
const PlaylistSidebar = lazy(() => import('../features/playlists/PlaylistSidebar'));
const LanguageSelector = lazy(() => import('../localization/LanguageSelector').then((module) => ({
  default: module.LanguageSelector
})));
const ShellPanelResizers = lazy(() => import('./ShellPanelResizers').then((module) => ({
  default: module.ShellPanelResizers
})));
const NowPlayingAside = lazy(() => import('../components/NowPlayingAside').then((module) => ({
  default: module.NowPlayingAside
})));
const PlayerBar = lazy(() => import('../components/PlayerBar').then((module) => ({
  default: module.PlayerBar
})));
const VideoTheater = lazy(() => import('../components/VideoTheater'));
const GlobalRoomInvitations = lazy(() => import('../features/social/GlobalRoomInvitations').then(module => ({
  default: module.GlobalRoomInvitations
})));
const AccountEntry = lazy(() => import('./AccountEntry').then(module => ({ default: module.AccountEntry })));
const AdminControls = lazy(() => import('../features/admin/AdminAccess').then(module => ({ default: module.AdminControls })));

/** Activates the shell skip link without changing the routed URL. */
const skipToMainContent = (event: MouseEvent<HTMLAnchorElement>) => {
  event.preventDefault();
  document.getElementById('main-content')?.focus({ preventScroll: true });
};

const PrimaryNavigation = ({ mobile = false }: { mobile?: boolean }) => {
  const location = useLocation();
  const { t } = useLocalization();
  // Together stays reachable by address for preserved safety actions, but is not advertised while disabled.
  const { socialEnabled } = useSocialAvailability();
  return (
    <nav
      className={mobile ? styles.mobileNavigation : styles.navigation}
      aria-label={t('shell.nav.primary_label')}
    >
      {destinations.filter((destination) => socialEnabled || destination.path !== '/social').map((destination) => {
        const label = t(destination.labelKey);
        const libraryOwnsRoute = destination.path === '/library'
          && (location.pathname === '/playlists' || location.pathname.startsWith('/playlists/'));
        return (
          <NavLink
            aria-current={libraryOwnsRoute ? 'page' : undefined}
            aria-label={label}
            className={({ isActive }) => `${styles.navigationLink} ${isActive || libraryOwnsRoute ? styles.active : ''}`}
            end={destination.path === '/'}
            key={destination.path}
            to={destination.path}
          >
            <Icon name={destination.icon} />
            <span>{label}</span>
          </NavLink>
        );
      })}
    </nav>
  );
};

/** Keeps one listening runtime behind listener routes and the independent management workspace. */
const AppShellContent = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const capabilities = useQuery(listenerCapabilitiesQuery());
  const [nowPlayingOpen, setNowPlayingOpen] = useState(true);
  const [widePanelResizersEnabled, setWidePanelResizersEnabled] = useState(false);
  const shellRef = useRef<HTMLDivElement>(null);
  const player = usePlayer(playerStore);
  const { t } = useLocalization();
  const videoPlaying = player.currentItem?.mediaType === 'video';
  const adminRoute = location.pathname === '/admin' || location.pathname.startsWith('/admin/');
  const effectiveNowPlayingOpen = videoPlaying || nowPlayingOpen;
  const listenerVideoVisible = videoPlaying && !adminRoute;

  useEffect(() => {
    if (typeof window.matchMedia !== 'function') {
      setWidePanelResizersEnabled(window.innerWidth >= 1008);
      return undefined;
    }

    const wideLayout = window.matchMedia('(min-width: 1008px)');
    const updateAvailability = () => setWidePanelResizersEnabled(wideLayout.matches);
    updateAvailability();
    wideLayout.addEventListener?.('change', updateAvailability);
    return () => wideLayout.removeEventListener?.('change', updateAvailability);
  }, []);

  return (
    <div
      className={adminRoute ? styles.adminShell : styles.shell}
      data-now-playing-open={!adminRoute && effectiveNowPlayingOpen}
      data-video-playing={listenerVideoVisible || undefined}
      ref={shellRef}
    >
      <a className={styles.skipLink} href="#main-content" onClick={skipToMainContent}>
        {t('shell.skip_to_main')}
      </a>
      <RouteAnnouncer />

      <header className={styles.topbar}>
        <Link className={styles.brand} to="/" aria-label={t('shell.brand.home_label')}>
          <span className={styles.brandMark} aria-hidden="true"><Icon name="brand" /></span>
          <span className={styles.brandName}>Finitude</span>
        </Link>

        <div className={styles.topbarCenter} aria-hidden={adminRoute || undefined} hidden={adminRoute} inert={adminRoute || undefined}>
          <div className={styles.historyControls} aria-label={t('shell.history.label')}>
            <button type="button" onClick={() => navigate(-1)} aria-label={t('shell.history.back')} title={t('shell.history.back')}>
              <Icon name="arrow-left" />
            </button>
            <button type="button" onClick={() => navigate(1)} aria-label={t('shell.history.forward')} title={t('shell.history.forward')}>
              <Icon name="arrow-right" />
            </button>
          </div>
          <Suspense fallback={<div className={styles.search} aria-hidden="true" />}><TopSearch /></Suspense>
        </div>

        {!adminRoute && <Suspense fallback={null}>
          <LanguageSelector placement="mobile" />
        </Suspense>}
        <div className={styles.accountActions}>
          <Suspense fallback={null}><AdminControls hideWorkbenchLink={adminRoute} /></Suspense>
          {capabilities.data?.social?.enabled && <Suspense fallback={null}><GlobalRoomInvitations hideEntries={adminRoute} /></Suspense>}
          {adminRoute && <Suspense fallback={null}><LanguageSelector placement="header" /></Suspense>}
          <Suspense fallback={<span className={styles.accountLoading} aria-hidden="true" />}><AccountEntry /></Suspense>
        </div>
      </header>

      <aside className={styles.sidebar} aria-hidden={adminRoute || undefined} aria-label={t('shell.sidebar.label')} hidden={adminRoute} inert={adminRoute || undefined} id="library-sidebar">
        <PrimaryNavigation />
        {capabilities.data?.playlists && !adminRoute && (
          <Suspense fallback={<div className={styles.sidebarLoading} aria-hidden="true" />}>
            <PlaylistSidebar />
          </Suspense>
        )}
        <Suspense fallback={null}>
          <LanguageSelector active={!adminRoute} />
        </Suspense>
      </aside>

      {widePanelResizersEnabled && !videoPlaying && !adminRoute && (
        <Suspense fallback={null}>
          <ShellPanelResizers nowPlayingOpen={effectiveNowPlayingOpen} shellRef={shellRef} />
        </Suspense>
      )}

      <div className={styles.workspace}>
        <main
          aria-hidden={listenerVideoVisible || undefined}
          className={styles.main}
          data-obscured={listenerVideoVisible || undefined}
          id="main-content"
          inert={listenerVideoVisible ? true : undefined}
          tabIndex={-1}
        >
          <Outlet />
        </main>
        {videoPlaying && (
          <div className={styles.videoSlot} aria-hidden={adminRoute || undefined} hidden={adminRoute} inert={adminRoute || undefined}>
            <Suspense fallback={<div className={styles.videoLoading} aria-hidden="true" />}>
              <VideoTheater />
            </Suspense>
          </div>
        )}
      </div>

      <aside
        aria-hidden={adminRoute || !effectiveNowPlayingOpen || undefined}
        aria-label={t('shell.now_playing.details_label')}
        className={styles.nowPlayingSlot}
        id="now-playing-aside"
        hidden={adminRoute}
        inert={adminRoute || !effectiveNowPlayingOpen ? true : undefined}
      >
        <Suspense fallback={<div className={styles.asideLoading} aria-hidden="true" />}>
          <NowPlayingAside />
        </Suspense>
      </aside>

      <div className={styles.playerSlot} aria-hidden={adminRoute || undefined} hidden={adminRoute} inert={adminRoute || undefined}>
        <Suspense fallback={<div className={styles.playerLoading} aria-hidden="true" />}>
          <PlayerBar
            active={!adminRoute}
            nowPlayingOpen={effectiveNowPlayingOpen}
            onToggleNowPlaying={videoPlaying
              ? undefined
              : () => setNowPlayingOpen((open) => !open)}
          />
        </Suspense>
      </div>
      {!adminRoute && <PrimaryNavigation mobile />}
    </div>
  );
};

/** Shares one Search draft across the shell search field and Search page. */
export const AppShell = () => (
  <SearchQueryProvider>
    <AppShellContent />
  </SearchQueryProvider>
);
